INSERT INTO breathing_styles (id, name, type, derived_from_id, user_ids, technique_ids, description, theme, image) VALUES ('sun-breathing', 'Sun Breathing', 'breathing-style', NULL, ARRAY['tanjiro-kamado']::text[], ARRAY['dance','clear-blue-sky','raging-sun','burning-bones-summer-sun','setting-sun-transformation','solar-heat-haze','beneficent-radiance','sunflower-thrust','dragon-sun-halo-head-dance','fire-wheel','fake-rainbow','flame-dance']::text[], 'The original Breathing Style from which the major derivative styles developed. Its forms imitate the movement, heat and radiance of the sun.', '{"primary": "#f59e0b", "secondary": "#dc2626"}'::jsonb, '/images/breathing/sun-breathing.png') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, derived_from_id = EXCLUDED.derived_from_id, user_ids = EXCLUDED.user_ids, technique_ids = EXCLUDED.technique_ids, description = EXCLUDED.description, theme = EXCLUDED.theme, image = EXCLUDED.image;
INSERT INTO breathing_styles (id, name, type, derived_from_id, user_ids, technique_ids, description, theme, image) VALUES ('water-breathing', 'Water Breathing', 'breathing-style', 'sun-breathing', ARRAY['giyu-tomioka','tanjiro-kamado']::text[], ARRAY['water-surface-slash','water-wheel','flowing-dance','striking-tide','blessed-rain-after-the-drought','whirlpool','drop-ripple-thrust','waterfall-basin','splashing-water-flow','constant-flux','dead-calm']::text[], 'A flowing Breathing Style that imitates the flexibility and adaptability of water. Its techniques emphasize smooth movement and continuous attacks.', '{"primary": "#38bdf8", "secondary": "#1d4ed8"}'::jsonb, '/images/breathing/water-breathing.png') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, derived_from_id = EXCLUDED.derived_from_id, user_ids = EXCLUDED.user_ids, technique_ids = EXCLUDED.technique_ids, description = EXCLUDED.description, theme = EXCLUDED.theme, image = EXCLUDED.image;
INSERT INTO breathing_styles (id, name, type, derived_from_id, user_ids, technique_ids, description, theme, image) VALUES ('flame-breathing', 'Flame Breathing', 'breathing-style', 'sun-breathing', ARRAY['kyojuro-rengoku']::text[], ARRAY['un-knowing-fire','rising-scorching-sun','blazing-universe','blooming-flame-undulation','flame-tiger','rengoku']::text[], 'A powerful offensive Breathing Style that imitates flames through explosive sword movements and forceful attacks.', '{"primary": "#f97316", "secondary": "#dc2626"}'::jsonb, '/images/breathing/flame-breathing.png') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, derived_from_id = EXCLUDED.derived_from_id, user_ids = EXCLUDED.user_ids, technique_ids = EXCLUDED.technique_ids, description = EXCLUDED.description, theme = EXCLUDED.theme, image = EXCLUDED.image;
INSERT INTO breathing_styles (id, name, type, derived_from_id, user_ids, technique_ids, description, theme, image) VALUES ('flower-breathing', 'Flower Breathing', 'breathing-style', 'water-breathing', ARRAY[]::text[], ARRAY[]::text[], 'A graceful derivative of Water Breathing that emphasizes agility, flowing swordsmanship and highly refined visual perception.', '{"primary": "#f9a8d4", "secondary": "#db2777"}'::jsonb, '/images/breathing/flower-breathing.png') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, derived_from_id = EXCLUDED.derived_from_id, user_ids = EXCLUDED.user_ids, technique_ids = EXCLUDED.technique_ids, description = EXCLUDED.description, theme = EXCLUDED.theme, image = EXCLUDED.image;
INSERT INTO breathing_styles (id, name, type, derived_from_id, user_ids, technique_ids, description, theme, image) VALUES ('insect-breathing', 'Insect Breathing', 'breathing-style', 'flower-breathing', ARRAY['shinobu-kocho']::text[], ARRAY['butterfly-dance-caprice','bee-sting-true-flutter','dragonfly-compound-eye-hexagon','centipede-hundred-legged-zigzag']::text[], 'A specialized Breathing Style created for rapid thrusting attacks and poison delivery rather than conventional decapitation.', '{"primary": "#c084fc", "secondary": "#7c3aed"}'::jsonb, '/images/breathing/insect-breathing.png') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, derived_from_id = EXCLUDED.derived_from_id, user_ids = EXCLUDED.user_ids, technique_ids = EXCLUDED.technique_ids, description = EXCLUDED.description, theme = EXCLUDED.theme, image = EXCLUDED.image;
INSERT INTO blood_demon_arts (id, name, type, user_id, ability_ids, description, theme, image) VALUES ('destructive-death', 'Destructive Death', 'blood-demon-art', 'akaza', ARRAY['compass-needle','air-type','disorder','annihilation-type','blue-silver-chaotic-afterglow']::text[], 'Akaza''s martial-arts-based Blood Demon Art. It enhances his close-range combat with destructive shockwaves and powerful attacks.', '{"primary": "#ec4899", "secondary": "#2563eb"}'::jsonb, '/images/blood-arts/destructive-death.png') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, user_id = EXCLUDED.user_id, ability_ids = EXCLUDED.ability_ids, description = EXCLUDED.description, theme = EXCLUDED.theme, image = EXCLUDED.image;
